"""Digital PDFs for the two synthetic HT electricity layouts (structure only, invented data)."""

from reportlab.lib import colors
from reportlab.lib.pagesizes import A4
from reportlab.lib.styles import getSampleStyleSheet
from reportlab.lib.units import mm
from reportlab.pdfgen import canvas
from reportlab.platypus import Paragraph, SimpleDocTemplate, Spacer, Table, TableStyle

FOOTER = (
    "Synthetic test document generated by billx synth. Invented values, not issued by any discom."
)
STYLES = getSampleStyleSheet()
GRID = [
    ("GRID", (0, 0), (-1, -1), 0.5, colors.black),
    ("FONTSIZE", (0, 0), (-1, -1), 7),
    ("VALIGN", (0, 0), (-1, -1), "TOP"),
    ("TOPPADDING", (0, 0), (-1, -1), 1.5),
    ("BOTTOMPADDING", (0, 0), (-1, -1), 1.5),
]


def _cell(label: str, value: str) -> Paragraph:
    return Paragraph(f"<font size=6>{label}</font><br/><b>{value}</b>", STYLES["BodyText"])


def _heading(text: str) -> Paragraph:
    return Paragraph(f"<b>{text}</b>", STYLES["Heading5"])


def footer(c, _doc) -> None:
    c.setFont("Helvetica", 6)
    c.drawString(14 * mm, 8 * mm, FOOTER)


def avvnl_pdf(bill: dict, path) -> None:
    """Bordered grid of labelled cells, (A) meter reading by TOD slot, (B) billing details."""
    v, p, h = bill["values"], bill["printed"], bill["header"]
    cells = [
        ("KNO", p["consumer.account_number"]),
        ("A/c No", h["A/c No"]),
        ("Bill No", bill["facts"]["bill_number"]["printed"]),
        ("Billing Month", p["period.bill_month"]),
        ("Tariff Code", p["tariff.category"]),
        ("Area Code", h["Area Code"]),
        ("Feeder Code", h["Feeder Code"]),
        ("Bill Issue Date", p["period.bill_date"]),
        ("Due Date of Payment", p["period.due_date"]),
        ("Voltage of Supply", h["Voltage of Supply"]),
        ("Metering side", h["Metering side"]),
        ("Sanction Load", h["Sanction Load"]),
        ("Contract Demand (KVA)", p["demand.contract_kva"]),
        ("75% of CD", h["75% of CD"]),
        ("Reading Date (Present)", p["period.to"]),
        ("Reading Date (Past)", p["period.from"]),
    ]
    grid = [[_cell(*c) for c in cells[i : i + 4]] for i in range(0, 16, 4)]
    grid.append(
        [
            _cell(
                "Name &amp; Address of Consumer",
                f"{v['consumer.name']}<br/>{h['Address']}<br/>GSTIN: {h['GSTIN']}",
            ),
            "",
            "",
            "",
        ]
    )
    info = Table(grid, colWidths=[45 * mm] * 4)
    info.setStyle(TableStyle(GRID + [("SPAN", (0, 4), (3, 4))]))

    meter = [["Register", "TOD Slot", "Present", "Past", "Difference", "MF", "Consumption"]]
    for reg, name in (("kwh", "kWh"), ("kvah", "kVAh")):
        for r in bill["tod"][reg] + [bill["tod"][f"{reg}_total"]]:
            q = r["printed"]
            meter.append(
                [
                    name,
                    r["slot"],
                    q["present"],
                    q["past"],
                    q["difference"],
                    q["mf"],
                    q["consumption"],
                ]
            )
    meter.append(["Recorded MD (KVA)", "", "", "", "", "", p["demand.max_kva"]])
    meter.append(["Billing Demand (KVA)", "", "", "", "", "", h["Billing Demand (KVA)"]])
    mt = Table(meter, colWidths=[30 * mm, 26 * mm, 24 * mm, 24 * mm, 24 * mm, 14 * mm, 38 * mm])
    mt.setStyle(
        TableStyle(
            GRID
            + [
                ("ALIGN", (2, 1), (-1, -1), "RIGHT"),
                ("FONTNAME", (0, 0), (-1, 0), "Helvetica-Bold"),
            ]
        )
    )

    rows = [["S.No", "Particulars", "Unit", "Quantity", "Rate (Rs.)", "Amount (Rs.)"]]
    for i, x in enumerate(bill["charges"], 1):
        q = x["printed"]
        rows.append([str(i), x["label"], x["unit"], q["quantity"], q["rate"], q["amount"]])
    n = len(rows)
    rows += [
        ["", "Current Charges (A)", "", "", "", p["totals.current_charges"]],
        ["", "Arrears (B)", "", "", "", p["totals.arrears"]],
        ["", "Net Payable (A+B)", "", "", "", p["totals.net_payable"]],
    ]
    ct = Table(rows, colWidths=[10 * mm, 62 * mm, 16 * mm, 32 * mm, 22 * mm, 38 * mm])
    ct.setStyle(
        TableStyle(
            GRID
            + [
                ("ALIGN", (3, 1), (-1, -1), "RIGHT"),
                ("FONTNAME", (0, 0), (-1, 0), "Helvetica-Bold"),
                ("FONTNAME", (0, n), (-1, -1), "Helvetica-Bold"),
            ]
        )
    )

    doc = SimpleDocTemplate(
        str(path),
        pagesize=A4,
        leftMargin=14 * mm,
        rightMargin=14 * mm,
        topMargin=10 * mm,
        bottomMargin=14 * mm,
        invariant=1,
        title="Synthetic AVVNL-style HT bill",
        author="billx synth",
    )
    doc.build(
        [
            Paragraph("<b>AJMER VIDYUT VITRAN NIGAM LIMITED (AVVNL)</b>", STYLES["Title"]),
            Paragraph(
                "HT / Large Industrial Power - Electricity Bill (synthetic layout)",
                STYLES["Normal"],
            ),
            Spacer(1, 3 * mm),
            info,
            _heading("(A) METER READING &amp; CONSUMPTION"),
            mt,
            _heading("(B) BILLING DETAILS"),
            ct,
            Spacer(1, 3 * mm),
            Paragraph(
                "Please pay the Net Payable amount by the due date to avoid surcharge.",
                STYLES["Normal"],
            ),
        ],
        onFirstPage=footer,
        onLaterPages=footer,
    )


def pvvnl_pdf(bill: dict, path) -> None:
    """Dot-matrix style 'bill cum notice': colon-aligned key values and a monospace TOD table."""
    v, p, h = bill["values"], bill["printed"], bill["header"]
    c = canvas.Canvas(str(path), pagesize=A4, invariant=1)
    c.setTitle("Synthetic PVVNL-style HV-2 bill")
    c.setAuthor("billx synth")
    w, top = A4[0], A4[1] - 18 * mm
    c.setFont("Courier-Bold", 12)
    c.drawCentredString(w / 2, top, "PASCHIMANCHAL VIDYUT VITRAN NIGAM LTD. (PVVNL)")
    c.setFont("Courier-Bold", 11)
    c.drawCentredString(w / 2, top - 14, "ELECTRICITY BILL CUM NOTICE")
    c.setFont("Courier", 8)
    c.drawCentredString(w / 2, top - 26, h["Division"])
    c.line(15 * mm, top - 32, w - 15 * mm, top - 32)

    left = [
        ("Bill No", bill["facts"]["bill_number"]["printed"]),
        ("Bill Date", p["period.bill_date"]),
        ("Due Date", p["period.due_date"]),
        ("Discont-Dt", h["Discont-Dt"]),
        ("AC-No", p["consumer.account_number"]),
        ("Bill Month", p["period.bill_month"]),
        ("Tariff Cd", p["tariff.category"]),
    ]
    right = [
        ("Meter-No", p["meter.number"]),
        ("CT Ratio", h["CT Ratio"]),
        ("PT Ratio", h["PT Ratio"]),
        ("Sup. Volt (KV)", h["Sup. Volt (KV)"]),
        ("Contracted Demand (KVA)", p["demand.contract_kva"]),
        ("Billable Demand (KVA) (75%)", h["Billable Demand (KVA) (75%)"]),
        ("Recorded MD (KVA)", p["demand.max_kva"]),
    ]
    y = top - 46
    c.setFont("Courier", 8)
    for (lk, lv), (rk, rv) in zip(left, right, strict=True):
        c.drawString(15 * mm, y, f"{lk:<11}: {lv}")
        c.drawString(100 * mm, y, f"{rk:<28}: {rv}")
        y -= 11
    y -= 4
    c.drawString(15 * mm, y, f"Name    : {v['consumer.name']}")
    c.drawString(15 * mm, y - 11, f"Address : {h['Address']}")
    y -= 28
    c.drawString(15 * mm, y, f"Reading Period : {p['period.from']} to {p['period.to']}")
    y -= 8
    c.line(15 * mm, y, w - 15 * mm, y)
    y -= 11
    c.setFont("Courier-Bold", 8)
    c.drawString(
        15 * mm,
        y,
        f"{'ENERGY':<11}{'PRESENT':>14}{'PAST':>14}{'DIFFERENCE':>13}{'M.F.':>8}{'TOTAL':>18}",
    )
    c.setFont("Courier", 8)
    for reg, name in (("kwh", "KWH"), ("kvah", "KVAH")):
        y -= 13
        c.setFont("Courier-Bold", 8)
        c.drawString(15 * mm, y, name)
        c.setFont("Courier", 8)
        for r in bill["tod"][reg] + [bill["tod"][f"{reg}_total"]]:
            y -= 11
            q = r["printed"]
            slot = f"{name} TOTAL" if r["slot"] == "Total" else r["slot"]
            c.drawString(
                15 * mm,
                y,
                f"{slot:<11}{q['present']:>14}{q['past']:>14}"
                f"{q['difference']:>13}{q['mf']:>8}{q['consumption']:>18}",
            )
    y -= 8
    c.line(15 * mm, y, w - 15 * mm, y)
    y -= 13
    c.setFont("Courier-Bold", 8)
    c.drawString(15 * mm, y, f"{'PARTICULARS':<26}{'UNITS':>18}{'RATE':>10}{'AMOUNT (RS)':>20}")
    c.setFont("Courier", 8)
    for x in bill["charges"]:
        y -= 11
        q = x["printed"]
        c.drawString(
            15 * mm, y, f"{x['label']:<26}{q['quantity']:>18}{q['rate']:>10}{q['amount']:>20}"
        )
    y -= 8
    c.line(15 * mm, y, w - 15 * mm, y)
    c.setFont("Courier-Bold", 9)
    for label, key in (
        ("CURRENT DUES", "totals.current_charges"),
        ("ARREARS", "totals.arrears"),
        ("NET PAYABLE", "totals.net_payable"),
    ):
        y -= 13
        c.drawString(15 * mm, y, f"{label:<54}{p[key]:>20}")
    c.setFont("Courier", 7)
    y -= 24
    c.drawString(
        15 * mm,
        y,
        "NOTICE: if the net payable is not paid by the due date, supply is "
        "liable to be disconnected after the Discont-Dt.",
    )
    c.setFont("Helvetica", 6)
    c.drawString(15 * mm, 8 * mm, FOOTER)
    c.showPage()
    c.save()
